package com.ilker.microsoftreport;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.provider.OpenableColumns;import android.view.*;import android.widget.*;import java.io.InputStream;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.Locale;import java.util.concurrent.*;
public final class MainActivity extends Activity{
 private static final int REQUEST_ENV=4201,REQUEST_NOTIFY=4202;private final ExecutorService executor=Executors.newSingleThreadExecutor();private TextView statusText,configText,totalQty,totalGross,totalNet,lastCheck;private LinearLayout salesList;private ProgressBar progress;private Button selectEnv,refresh;private boolean receiverRegistered;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){boolean e=i.getBooleanExtra(PollService.EXTRA_ERROR,false);String s=i.getStringExtra(PollService.EXTRA_STATUS);setStatus(s==null?"":s,e);renderDashboard();}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);buildUi();requestNotificationsIfNeeded();renderConfigState();renderDashboard();if(new AuthStore(this).hasConfig())PollService.ensureRunning(this);}
 @Override protected void onStart(){super.onStart();if(!receiverRegistered){IntentFilter f=new IntentFilter(PollService.ACTION_STATUS);if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,f);receiverRegistered=true;}renderDashboard();}@Override protected void onStop(){if(receiverRegistered){unregisterReceiver(receiver);receiverRegistered=false;}super.onStop();}@Override protected void onDestroy(){executor.shutdownNow();super.onDestroy();}
 private void buildUi(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(245,247,250));LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(24),dp(18),dp(36));scroll.addView(root,new ScrollView.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));root.addView(text("Microsoft Store Analytics",26,Color.rgb(25,33,43),Typeface.BOLD));TextView sub=text("Türkiye saati • USD • Microsoft API • 2 dk arka plan kontrolü",13,Color.rgb(88,98,112),Typeface.NORMAL);sub.setPadding(0,dp(4),0,dp(18));root.addView(sub);LinearLayout cb=box();cb.addView(text("MICROSOFT BAĞLANTISI",12,Color.rgb(73,83,98),Typeface.BOLD));configText=text("ENV bekleniyor",14,Color.rgb(25,33,43),Typeface.NORMAL);configText.setPadding(0,dp(8),0,dp(10));cb.addView(configText);selectEnv=button("ENV / TXT dosyası seç");selectEnv.setOnClickListener(v->selectEnvFile());cb.addView(selectEnv);root.addView(cb);LinearLayout sb=box();statusText=text("Durum: hazırlanıyor",14,Color.rgb(25,33,43),Typeface.NORMAL);sb.addView(statusText);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);progress.setVisibility(View.GONE);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(4));pp.topMargin=dp(10);sb.addView(progress,pp);root.addView(sb);LinearLayout sum=box();sum.addView(text("BUGÜN",12,Color.rgb(73,83,98),Typeface.BOLD));totalQty=metric(sum,"Satılan","0");totalGross=metric(sum,"Brüt","$0.00");totalNet=metric(sum,"Net","$0.00");lastCheck=metric(sum,"Son kontrol","--");root.addView(sum);refresh=button("Şimdi kontrol et");refresh.setOnClickListener(v->{if(new AuthStore(this).hasConfig()){setBusy(true,"Microsoft Store kontrol ediliyor");PollService.requestImmediate(this);}else setStatus("Önce ENV dosyasını seçin",true);});LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);rp.setMargins(0,dp(2),0,dp(14));root.addView(refresh,rp);TextView lt=text("BUGÜN SATILAN UYGULAMALAR",12,Color.rgb(73,83,98),Typeface.BOLD);lt.setPadding(dp(2),dp(6),0,dp(8));root.addView(lt);salesList=new LinearLayout(this);salesList.setOrientation(LinearLayout.VERTICAL);root.addView(salesList);TextView note=text("Net = Brüt − Microsoft Store acquisition verisindeki vergi. Partner Center payout/earning net değeri değildir.",12,Color.rgb(99,108,120),Typeface.NORMAL);note.setPadding(dp(4),dp(12),dp(4),0);root.addView(note);setContentView(scroll);}
 private TextView metric(LinearLayout p,String l,String init){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setPadding(0,dp(10),0,0);TextView a=text(l,14,Color.rgb(75,84,96),Typeface.NORMAL),v=text(init,16,Color.rgb(20,28,38),Typeface.BOLD);r.addView(a,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));r.addView(v);p.addView(r);return v;}
 private void renderConfigState(){boolean ready=new AuthStore(this).hasConfig();configText.setText(ready?"ENV yüklü • Tenant / Client / Secret cihazda kayıtlı":"TENANT_ID, CLIENT_ID ve CLIENT_SECRET içeren .env/.txt seçin");refresh.setEnabled(ready);if(!ready)setStatus("Microsoft erişim dosyası bekleniyor",false);}
 private void renderDashboard(){Models.Dashboard d=new StateStore(this).loadDashboard();salesList.removeAllViews();if(d==null){totalQty.setText("0");totalGross.setText("$0.00");totalNet.setText("$0.00");lastCheck.setText("--");TextView e=text("Henüz veri yok",14,Color.rgb(105,113,123),Typeface.NORMAL);e.setPadding(dp(4),dp(12),0,dp(12));salesList.addView(e);return;}totalQty.setText(String.valueOf(d.totalQuantity()));totalGross.setText(money(d.totalGross()));totalNet.setText(money(d.totalNet()));lastCheck.setText(formatTurkeyTime(d.checkedAt));if(d.sales.isEmpty()){TextView e=text("Bugün ücretli uygulama satışı yok",14,Color.rgb(105,113,123),Typeface.NORMAL);e.setPadding(dp(4),dp(12),0,dp(12));salesList.addView(e);}else for(Models.AppSale s:d.sales)addSaleRow(s);}
 private void addSaleRow(Models.AppSale s){LinearLayout c=box();c.addView(text(s.appName,17,Color.rgb(20,28,38),Typeface.BOLD));TextView d=text(s.quantity+" adet    Brüt "+money(s.grossUsd)+"    Net "+money(s.netUsd()),14,Color.rgb(55,65,78),Typeface.NORMAL);d.setPadding(0,dp(7),0,0);c.addView(d);salesList.addView(c);}
 private void selectEnvFile(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,REQUEST_ENV);}@Override protected void onActivityResult(int rc,int result,Intent data){super.onActivityResult(rc,result,data);if(rc!=REQUEST_ENV||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();String name=displayName(uri),lower=name.toLowerCase(Locale.ROOT);if(!(lower.endsWith(".env")||lower.endsWith(".txt"))){setStatus("Yalnızca .env veya .txt dosyası seçin",true);return;}setBusy(true,"ENV okunuyor ve Microsoft ile doğrulanıyor");executor.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IllegalStateException("Dosya açılamadı");EnvConfig cfg=EnvConfig.parse(in);int count=new MicrosoftApi(cfg).validate();new AuthStore(this).save(cfg);runOnUiThread(()->{setBusy(false,"Microsoft bağlantısı doğrulandı • "+count+" uygulama");renderConfigState();PollService.ensureRunning(this);PollService.requestImmediate(this);});}catch(Throwable e){runOnUiThread(()->setBusy(false,concise(e.getMessage())));}});}
 private String displayName(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()){int i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0)return c.getString(i);}}catch(Exception ignored){}String p=u.getLastPathSegment();return p==null?"config.env":p;}private void requestNotificationsIfNeeded(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},REQUEST_NOTIFY);}
 private void setBusy(boolean b,String s){progress.setVisibility(b?View.VISIBLE:View.GONE);selectEnv.setEnabled(!b);refresh.setEnabled(!b&&new AuthStore(this).hasConfig());setStatus(s,false);}private void setStatus(String s,boolean e){progress.setVisibility(View.GONE);statusText.setText((e?"Hata: ":"Durum: ")+(s==null||s.isEmpty()?"--":s));statusText.setTextColor(e?Color.rgb(180,40,40):Color.rgb(25,33,43));selectEnv.setEnabled(true);refresh.setEnabled(new AuthStore(this).hasConfig());}
 private LinearLayout box(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(16),dp(14),dp(16),dp(14));GradientDrawable g=new GradientDrawable();g.setColor(Color.WHITE);g.setCornerRadius(dp(12));g.setStroke(dp(1),Color.rgb(226,230,235));b.setBackground(g);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.setMargins(0,0,0,dp(12));b.setLayoutParams(lp);return b;}private Button button(String l){Button b=new Button(this);b.setText(l);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(Color.WHITE);GradientDrawable g=new GradientDrawable();g.setColor(Color.rgb(15,108,189));g.setCornerRadius(dp(9));b.setBackground(g);b.setPadding(dp(14),dp(10),dp(14),dp(10));return b;}private TextView text(String v,float sp,int c,int s){TextView t=new TextView(this);t.setText(v);t.setTextSize(sp);t.setTextColor(c);t.setTypeface(Typeface.create("sans",s));return t;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private static String money(double v){return String.format(Locale.US,"$%,.2f",v);}private static String formatTurkeyTime(String i){try{return DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm:ss",Locale.forLanguageTag("tr-TR")).withZone(ZoneId.of("Europe/Istanbul")).format(Instant.parse(i))+" TR";}catch(Exception e){return i==null||i.isEmpty()?"--":i;}}private static String concise(String s){if(s==null||s.trim().isEmpty())return"İşlem tamamlanamadı";String x=s.replaceAll("[\\r\\n\\t]+"," ").replaceAll("\\s{2,}"," ").trim();return x.length()>240?x.substring(0,240):x;}
}
